#!/usr/bin/env node
"use strict";

const fs = require("node:fs");
const path = require("node:path");
const vm = require("node:vm");
const {
  HUB_ROUTE,
  LANES,
  OWNERS,
  WORKSPACES,
  validateContract,
} = require("./lib/fr-creative-route-contract");

const ROOT = path.resolve(__dirname, "..");
const OUTPUT = path.join(ROOT, "fr", "creative", "index.html");
const SWAHILI_OUTPUT = path.join(
  ROOT,
  "sw",
  "ubunifu-na-watayarishi",
  "index.html"
);
const SWAHILI_FRENCH_ALTERNATE =
  '<link rel="alternate" hreflang="fr" href="https://afrotools.com/fr/creative/">';
const REGISTRY = path.join(
  ROOT,
  "assets",
  "js",
  "components",
  "tool-registry.js"
);

function escapeHtml(value) {
  return String(value).replace(
    /[&<>"']/g,
    (character) =>
      ({
        "&": "&amp;",
        "<": "&lt;",
        ">": "&gt;",
        '"': "&quot;",
        "'": "&#39;",
      })[character]
  );
}

function readRegistry() {
  const context = { console: { log() {}, warn() {}, error() {} } };
  vm.runInNewContext(
    `${fs.readFileSync(REGISTRY, "utf8")}\nglobalThis.__AFRO_TOOLS__ = AFRO_TOOLS;`,
    context,
    { filename: REGISTRY }
  );
  return context.__AFRO_TOOLS__;
}

function resolveTools() {
  validateContract();
  const registry = readRegistry();
  const byOwner = new Map();

  for (const [englishId, frenchSlug] of OWNERS) {
    const href = `/fr/tools/${frenchSlug}/`;
    const matches = registry.filter(
      (tool) =>
        tool.href === href &&
        tool.lang === "fr" &&
        tool.category === "creative" &&
        (tool.sourceId || tool.id) === englishId
    );
    if (matches.length !== 1) {
      throw new Error(
        `${href} must have exactly one French Creative registry owner; found ${matches.length}.`
      );
    }
    const tool = matches[0];
    const artwork = path.join(
      ROOT,
      "assets",
      "img",
      "tools",
      `${tool.imageId || englishId}.webp`
    );
    if (!fs.existsSync(artwork)) {
      throw new Error(`${href} is missing owned artwork ${path.relative(ROOT, artwork)}.`);
    }
    byOwner.set(englishId, {
      ...tool,
      englishId,
      frenchSlug,
      imageId: tool.imageId || englishId,
    });
  }

  return byOwner;
}

function renderToolCard(tool) {
  return `<article class="creative-card">
  <a href="${tool.href}">
    <img src="/assets/img/tools/${escapeHtml(tool.imageId)}.webp" alt="" width="320" height="180" loading="lazy">
    <span class="creative-card-copy">
      <strong>${escapeHtml(tool.name)}</strong>
      <span>${escapeHtml(tool.desc)}</span>
      <em>Ouvrir l’outil <span aria-hidden="true">→</span></em>
    </span>
  </a>
</article>`;
}

function render() {
  const byOwner = resolveTools();
  const canonical = "https://afrotools.com/fr/creative/";
  const english = "https://afrotools.com/creative/";
  const itemList = OWNERS.map(([englishId], index) => {
    const tool = byOwner.get(englishId);
    return {
      "@type": "ListItem",
      position: index + 1,
      url: `https://afrotools.com${tool.href}`,
      name: tool.name,
    };
  });
  const laneMarkup = LANES.map((lane) => `<section class="creative-lane" id="${lane.id}" aria-labelledby="${lane.id}-title">
  <div class="creative-lane-head">
    <p>${lane.ownerIds.length} outils</p>
    <h2 id="${lane.id}-title">${lane.title}</h2>
    <span>${lane.description}</span>
  </div>
  <div class="creative-grid">
${lane.ownerIds.map((ownerId) => renderToolCard(byOwner.get(ownerId))).join("\n")}
  </div>
</section>`).join("\n");

  const schemas = [
    {
      "@context": "https://schema.org",
      "@type": "CollectionPage",
      name: "Économie créative — outils en français",
      description:
        "46 outils et 33 espaces de travail pour planifier, produire, publier et monétiser une activité créative.",
      inLanguage: "fr",
      url: canonical,
      isPartOf: {
        "@type": "WebSite",
        name: "AfroTools",
        url: "https://afrotools.com/",
      },
    },
    {
      "@context": "https://schema.org",
      "@type": "ItemList",
      name: "Outils AfroTools pour l’économie créative",
      numberOfItems: OWNERS.length,
      inLanguage: "fr",
      itemListElement: itemList,
    },
    {
      "@context": "https://schema.org",
      "@type": "BreadcrumbList",
      itemListElement: [
        {
          "@type": "ListItem",
          position: 1,
          name: "Accueil",
          item: "https://afrotools.com/fr/",
        },
        {
          "@type": "ListItem",
          position: 2,
          name: "Économie créative",
          item: canonical,
        },
      ],
    },
  ];

  return `<!doctype html>
<!-- Generated by scripts/build-fr-creative-hub.js. -->
<html lang="fr">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <meta http-equiv="Content-Security-Policy" content="default-src 'self'; script-src 'self' 'unsafe-inline' blob:; style-src 'self' 'unsafe-inline'; img-src 'self' data: blob:; media-src 'self' data: blob:; connect-src 'self'; font-src 'self' data:; worker-src 'self' blob:; object-src 'none'; base-uri 'self'; form-action 'self'">
  <script src="/assets/js/pages/creative/fr-creative-privacy-bootstrap.js"></script>
  <meta name="afrotools-content-id" content="fr-creative:hub">
  <meta name="afrotools-source-owner" content="scripts/build-fr-creative-hub.js">
  <meta name="theme-color" content="#fffdf8">
  <title>Économie créative — outils en français | AfroTools</title>
  <meta name="description" content="46 outils et 33 espaces de travail en français pour planifier, produire, publier, chiffrer et monétiser une activité créative en Afrique.">
  <meta name="robots" content="index, follow">
  <link rel="canonical" href="${canonical}">
  <link rel="alternate" hreflang="en" href="${english}">
  <link rel="alternate" hreflang="fr" href="${canonical}">
  <link rel="alternate" hreflang="sw" href="https://afrotools.com/sw/ubunifu-na-watayarishi/">
  <link rel="alternate" hreflang="x-default" href="${english}">
  <meta property="og:type" content="website">
  <meta property="og:locale" content="fr_FR">
  <meta property="og:title" content="Économie créative — outils en français">
  <meta property="og:description" content="46 outils et 33 espaces de travail pour les créatrices, créateurs et équipes en Afrique.">
  <meta property="og:url" content="${canonical}">
  <meta property="og:image" content="https://afrotools.com/assets/img/tools/creator-desk.webp">
  <meta name="twitter:card" content="summary_large_image">
  <link rel="stylesheet" href="/assets/css/design-system.css">
  <link rel="stylesheet" href="/assets/css/fr-creative-route-real-proof.css">
  <style>
    :root{--cr-bg:#fffdf8;--cr-surface:#fff;--cr-ink:#172033;--cr-muted:#4b586f;--cr-line:#cbd3df;--cr-accent:#7a2600;--cr-accent-soft:#fff0e8;--cr-focus:#005fcc;color-scheme:light}
    html[data-theme="dark"]{--cr-bg:#111827;--cr-surface:#1f2937;--cr-ink:#f8fafc;--cr-muted:#d2d8e2;--cr-line:#596579;--cr-accent:#ffbd94;--cr-accent-soft:#3b251d;--cr-focus:#85b8ff;color-scheme:dark}
    @media(prefers-color-scheme:dark){html:not([data-theme="light"]){--cr-bg:#111827;--cr-surface:#1f2937;--cr-ink:#f8fafc;--cr-muted:#d2d8e2;--cr-line:#596579;--cr-accent:#ffbd94;--cr-accent-soft:#3b251d;--cr-focus:#85b8ff;color-scheme:dark}}
    *{box-sizing:border-box}body{margin:0;background:var(--cr-bg);color:var(--cr-ink);font-family:Inter,ui-sans-serif,system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}.skip-link{position:absolute;left:12px;top:12px;opacity:0;pointer-events:none}.skip-link:focus{z-index:1000;padding:12px;background:var(--cr-surface);color:var(--cr-ink);opacity:1;pointer-events:auto;outline:3px solid var(--cr-focus)}a:focus-visible,button:focus-visible{outline:3px solid var(--cr-focus);outline-offset:3px}.creative-shell{width:min(1180px,calc(100% - 32px));margin:auto}.creative-top{display:flex;align-items:center;justify-content:space-between;gap:16px;padding:18px 0}.creative-home{color:var(--cr-ink);font-weight:850;text-decoration:none}.creative-theme{min-height:44px;padding:9px 13px;border:1px solid var(--cr-line);border-radius:7px;background:var(--cr-surface);color:var(--cr-ink);font:inherit;font-weight:750;cursor:pointer}.creative-hero{padding:64px 0 54px;border-block:1px solid var(--cr-line)}.creative-kicker{margin:0 0 12px;color:var(--cr-accent);font-size:.8rem;font-weight:850;letter-spacing:.1em;text-transform:uppercase}.creative-hero h1{max-width:850px;margin:0;font-size:clamp(2.25rem,7vw,4.7rem);line-height:1.02;letter-spacing:-.04em}.creative-lead{max-width:760px;margin:22px 0 0;color:var(--cr-muted);font-size:1.12rem;line-height:1.72}.creative-counts{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px;margin-top:30px}.creative-counts div{padding:17px;border-left:4px solid var(--cr-accent);background:var(--cr-surface)}.creative-counts strong{display:block;font-size:1.55rem}.creative-counts span{color:var(--cr-muted)}.creative-trust{max-width:820px;margin:30px 0 0;padding:17px 19px;border:1px solid var(--cr-line);background:var(--cr-accent-soft);line-height:1.65}.creative-lane{padding:58px 0;border-bottom:1px solid var(--cr-line)}.creative-lane-head{display:grid;grid-template-columns:150px minmax(0,1fr) minmax(250px, .8fr);gap:24px;align-items:end;margin-bottom:25px}.creative-lane-head p{margin:0;color:var(--cr-accent);font-weight:850}.creative-lane-head h2{margin:0;font-size:clamp(1.55rem,4vw,2.5rem)}.creative-lane-head span{color:var(--cr-muted);line-height:1.6}.creative-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px}.creative-card{min-width:0;border:1px solid var(--cr-line);background:var(--cr-surface)}.creative-card a{display:grid;height:100%;color:var(--cr-ink);text-decoration:none}.creative-card img{display:block;width:100%;height:154px;object-fit:cover;background:var(--cr-accent-soft)}.creative-card-copy{display:grid;gap:10px;padding:17px}.creative-card strong{font-size:1.05rem;line-height:1.35}.creative-card-copy>span{color:var(--cr-muted);font-size:.94rem;line-height:1.55}.creative-card em{color:var(--cr-accent);font-style:normal;font-weight:850}.creative-card a:hover em{text-decoration:underline}.creative-close{padding:48px 0 70px}.creative-close h2{margin:0 0 12px}.creative-close p{max-width:760px;color:var(--cr-muted);line-height:1.7}
    @media(max-width:820px){.creative-lane-head{grid-template-columns:1fr;gap:8px}.creative-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}
    @media(max-width:560px){.creative-shell{width:min(100% - 24px,1180px)}.creative-hero{padding:42px 0}.creative-counts,.creative-grid{grid-template-columns:1fr}.creative-card a{grid-template-columns:96px minmax(0,1fr)}.creative-card img{height:100%;min-height:120px}.creative-lane{padding:42px 0}}
    @media(prefers-reduced-motion:reduce){*{scroll-behavior:auto!important;transition:none!important}}
  </style>
  <script type="application/ld+json">${JSON.stringify(schemas)}</script>
  <script>(function(){var saved=null;try{saved=localStorage.getItem("aft_theme")}catch(error){}if(saved==="dark"||saved==="light")document.documentElement.dataset.theme=saved;}());</script>
</head>
<body>
  <a class="skip-link" href="#creative-content">Aller aux outils</a>
  <header class="creative-shell creative-top">
    <a class="creative-home" href="/fr/" aria-label="AfroTools, accueil en français">AfroTools</a>
    <button class="creative-theme" id="creativeTheme" type="button" aria-pressed="false">Thème sombre</button>
  </header>
  <main id="creative-content">
    <section class="creative-hero">
      <div class="creative-shell">
        <p class="creative-kicker">Économie créative</p>
        <h1>Des outils concrets pour faire avancer votre travail créatif</h1>
        <p class="creative-lead">Choisissez votre tâche : planifier une publication, préparer un média, fixer un prix, partager des revenus ou organiser une équipe. Chaque outil garde ses calculs et ses fichiers dans votre navigateur sauf consentement explicite.</p>
        <div class="creative-counts" aria-label="Couverture de la catégorie">
          <div><strong>${OWNERS.length}</strong><span>pages de lancement</span></div>
          <div><strong>${WORKSPACES.length}</strong><span>espaces de travail</span></div>
          <div><strong>${OWNERS.length + WORKSPACES.length + 1}</strong><span>routes physiques, hub compris</span></div>
        </div>
        <p class="creative-trust"><strong>Privé par défaut.</strong> Les outils de cette sélection fonctionnent localement. Les estimations de prix, revenus ou audience doivent être rapprochées de vos contrats, plateformes et marchés.</p>
      </div>
    </section>
    <div class="creative-shell">
${laneMarkup}
      <section class="creative-close">
        <h2>Commencez par le travail à accomplir</h2>
        <p>Les 46 pages ci-dessus sont les entrées canoniques françaises. Les 33 outils Creator qui disposent d’un espace avancé l’ouvrent depuis leur page de lancement, sans route implicite ni compteur gonflé.</p>
      </section>
    </div>
  </main>
  <script>
  (function(){
    var button=document.getElementById("creativeTheme");
    function dark(){return document.documentElement.dataset.theme==="dark"||(!document.documentElement.dataset.theme&&matchMedia("(prefers-color-scheme: dark)").matches)}
    function sync(){var active=dark();button.setAttribute("aria-pressed",String(active));button.textContent=active?"Thème clair":"Thème sombre"}
    button.addEventListener("click",function(){var next=dark()?"light":"dark";document.documentElement.dataset.theme=next;try{localStorage.setItem("aft_theme",next)}catch(error){}sync()});
    sync();
  }());
  </script>
  <script src="/assets/js/pages/creative/fr-creative-route-real-reflow.js" defer></script>
  <script src="/assets/js/pages/creative/fr-creative-consent-analytics.js" defer></script>
</body>
</html>
`;
}

function main() {
  const content = render();
  const current = fs.existsSync(OUTPUT) ? fs.readFileSync(OUTPUT, "utf8") : "";
  const swahiliCurrent = fs.readFileSync(SWAHILI_OUTPUT, "utf8");
  const swahiliContent = swahiliCurrent.includes(SWAHILI_FRENCH_ALTERNATE)
    ? swahiliCurrent
    : swahiliCurrent.replace(
        '<link rel="alternate" hreflang="sw" href="https://afrotools.com/sw/ubunifu-na-watayarishi/">',
        `${SWAHILI_FRENCH_ALTERNATE}\n<link rel="alternate" hreflang="sw" href="https://afrotools.com/sw/ubunifu-na-watayarishi/">`
      );
  const check = process.argv.includes("--check");
  if (check && (current !== content || swahiliCurrent !== swahiliContent)) {
    throw new Error("French Creative hub is stale. Run npm run fr:creative:hub.");
  }
  if (!check && current !== content) {
    fs.mkdirSync(path.dirname(OUTPUT), { recursive: true });
    fs.writeFileSync(OUTPUT, content);
  }
  if (!check && swahiliCurrent !== swahiliContent) {
    fs.writeFileSync(SWAHILI_OUTPUT, swahiliContent);
  }
  console.log(
    `French Creative hub ${check ? "verified" : "built"}: ${OWNERS.length} launchers + ${WORKSPACES.length} workspaces + hub = ${OWNERS.length + WORKSPACES.length + 1}.`
  );
}

try {
  main();
} catch (error) {
  console.error(error.message);
  process.exitCode = 1;
}
